{
  "apiVersion": 1,
  "type": "component.detail.props",
  "package": "@astryxdesign/lab",
  "data": [
    {
      "name": "view",
      "type": "ScheduleView<Options>",
      "description": "The view object that owns the layout and the date range each page covers. Build one with createScheduleMonthlyView, createScheduleWeeklyView, createScheduleDayView, or createScheduleListView; each factory takes its own options (weekStartsOn, minHour/maxHour/hourHeight, days). The week, day, and month factories also take renderPopover(event): return the content for an event and the view renders that event as a button that opens a popover it manages — one popover for the view, named by the event title, with the system's standard surface, padding, Escape and light dismiss, and focus return; return null to leave an event read-only. In the month view that popover also shows a busy day's list, and a row in the list opens its event in place. The list view has no interaction option.",
      "required": true
    },
    {
      "name": "events",
      "type": "ReadonlyArray<CalendarEvent> | ((start: Instant, end: Instant) => Promise<ReadonlyArray<CalendarEvent>>)",
      "description": "Either a static array, filtered to the events overlapping the rendered range and sorted by start, or a loader called with that range's start and end epoch milliseconds. A loader suspends while pending; the header shows a spinner and the view renders empty. Results are cached per loader identity and range, so keep the loader reference stable (useCallback) or every re-render refetches. When your page already holds the events, pass them as an array; Schedule picks out each range's events without a loader.",
      "required": true
    },
    {
      "name": "categories",
      "type": "ReadonlyArray<{label: string, color: 'red' | 'orange' | 'yellow' | 'green' | 'teal' | 'cyan' | 'blue' | 'purple' | 'pink' | 'gray'}>",
      "description": "Category definitions matched to each event by label === event.category. The match supplies the event's color and the category name in its accessible label. An event whose category names no entry keeps that name but falls back to blue; an event with no category is announced as \"Event\" in blue. A category can stand for any grouping you color by — an event kind, a calendar, or a team; to color events by calendar, give each calendar its own entry.",
      "default": "[]"
    },
    {
      "name": "date",
      "type": "Instant",
      "description": "Unix epoch milliseconds anywhere inside the range to render; the view expands it to a full month, week, day, or list window. Fully controlled; Schedule never changes it, so pair it with onChangeDate.",
      "required": true
    },
    {
      "name": "focusDate",
      "type": "Instant",
      "description": "Unix epoch milliseconds marking the day treated as \"today\": in the month, week, and day views that cell gets aria-current=\"date\" and the highlighted styling. The list view ignores it. When omitted it is captured once at mount and never advances afterwards.",
      "default": "Date.now() at mount"
    },
    {
      "name": "onChangeDate",
      "type": "(date: Instant) => void",
      "description": "Called with the epoch milliseconds to render next when a pagination plugin pages backward or forward, or when Today is pressed. Paging preserves the time of day; Today passes the current time."
    },
    {
      "name": "timezoneID",
      "type": "string",
      "description": "IANA timezone ID (e.g. \"America/Los_Angeles\") used for every date calculation and every formatted label, so the same events regroup across days when it changes.",
      "default": "Intl.DateTimeFormat().resolvedOptions().timeZone"
    },
    {
      "name": "plugins",
      "type": "ReadonlyArray<SchedulePlugin>",
      "description": "Header plugins, applied in order; each may wrap or replace the start, center, and end header content. Supplying an array replaces the default pagination controls; compose useSchedulePaginationPlugin and useScheduleViewSelectorPlugin to keep both.",
      "default": "defaultSchedulePlugins"
    },
    {
      "name": "headingLevel",
      "type": "2 | 3 | 4 | 5 | 6",
      "description": "Heading level for sub-headings inside the schedule (the weekday and day column headers in the grid views, and the day headings in the list view), so the schedule nests correctly under the surrounding page outline. The header range title is always a level-2 heading.",
      "default": "3"
    }
  ],
  "meta": {
    "answeredBy": {
      "cli": "0.7.12",
      "core": "0.7.12",
      "copy": "starting"
    }
  }
}
